// Worker-side indexer: build package records straight from a GitHub release.
//
// Used for repositories that do NOT publish an `sspks-index.json` bundle. The
// Worker discovers the release without the REST API (302 tag redirect +
// `expanded_assets` HTML), streams the SPK into R2, then reads the metadata back
// with R2 range requests:
//
// - `INFO` (package name/version/description/arch/...) parsed from the tar
// - `PACKAGE_ICON.PNG` / `PACKAGE_ICON_256.PNG` (72 / 120 px) extracted and stored
// - `conf/privilege` (run-as root detection)
// - md5 taken from the R2 ETag: single-part uploads expose the MD5 digest there
//
// This is the bundle-less fallback; publishing a bundle is still cheaper and more
// robust, but a source works without any repo-side workflow.

const BLOCK = 512;
const MAX_INFO_BYTES = 4 * 1024 * 1024;
const MAX_IMAGE_BYTES = 20 * 1024 * 1024;
const REQUIRED_INFO_FIELDS = ['package', 'version', 'os_min_ver', 'description', 'arch', 'maintainer'];
const ARCH_LIST = /^[a-z0-9_]+(?:\s+[a-z0-9_]+)*$/i;
const DSM_VERSION = /^(\d+)\.(\d+)(?:\.(\d+))?-(\d+)$/;
const PACKAGE_VERSION = /^\d+(?:[._-]\d+)+$/;
const LOCALIZED_KEY = /^(displayname|description)_([a-z]{3})$/;
const SCREEN_NAME = /^screen_(\d{1,2})\.png$/i;
const INFO_LINE = /^\s*([A-Za-z][A-Za-z0-9_]*)\s*=(.*)$/;
const SAFE_FILE = /^[A-Za-z0-9._-]+\.spk$/i;

const DEFAULT_ICON_72 = 'icons/_default_72.png';
const DEFAULT_ICON_120 = 'icons/_default_120.png';

// assets/default_icon_{72,120}.png, embedded so a bundle-less source still gets
// a placeholder icon without shipping files with the Worker.
const DEFAULT_ICON_72_BASE64 = '';
const DEFAULT_ICON_120_BASE64 = '';

const GITHUB_HEADERS = {
  'User-Agent': 'sspks-cf-worker',
  Accept: 'text/html,application/xhtml+xml',
};

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return bytes;
}

/**
 * Discover the latest release tag and its `.spk` assets without the REST API.
 * @returns {Promise<{tag: string, files: string[]}>}
 */
export async function discoverRelease(env, repo) {
  const latestUrl = `https://github.com/${repo}/releases/latest`;
  let tag = '';
  const latest = await fetch(latestUrl, { headers: GITHUB_HEADERS, redirect: 'manual' });
  if (latest.status >= 300 && latest.status < 400) {
    const location = latest.headers.get('location') || '';
    const match = /\/releases\/tag\/([^/?#]+)/.exec(location);
    if (match) tag = decodeURIComponent(match[1]);
  }
  if (tag === '') {
    const html = await (await fetch(latestUrl, { headers: GITHUB_HEADERS, redirect: 'follow' })).text();
    const match = /\/releases\/tag\/([^"?#]+)/.exec(html);
    if (!match) throw new Error(`cannot resolve the latest release tag of ${repo}`);
    tag = decodeURIComponent(match[1]);
  }

  const fragmentUrl = `https://github.com/${repo}/releases/expanded_assets/${encodeURIComponent(tag)}`;
  const fragment = await fetch(fragmentUrl, { headers: GITHUB_HEADERS });
  if (!fragment.ok) throw new Error(`list assets of ${repo}@${tag}: HTTP ${fragment.status}`);
  const html = await fragment.text();
  const files = new Set();
  const pattern = /\/releases\/download\/[^/"]+\/([^"?#]+)/g;
  let match;
  while ((match = pattern.exec(html)) !== null) {
    let file;
    try {
      file = decodeURIComponent(match[1]);
    } catch {
      continue;
    }
    if (SAFE_FILE.test(file)) files.add(file);
  }
  return { tag, files: [...files].sort() };
}

/** Content-Length of a release asset (follows the GitHub → objects redirect). */
export async function assetSize(env, repo, tag, file) {
  const url = `https://github.com/${repo}/releases/download/${encodeURIComponent(tag)}/${encodeURIComponent(file)}`;
  const headers = { ...GITHUB_HEADERS };
  const token = String((env && env.GH_TOKEN) || '').trim();
  if (token !== '') headers.Authorization = `Bearer ${token}`;
  const response = await fetch(url, { method: 'HEAD', headers, redirect: 'follow' });
  if (response.status === 404) return null;
  if (!response.ok) throw new Error(`HEAD ${file}: HTTP ${response.status}`);
  const length = Number(response.headers.get('content-length'));
  return Number.isFinite(length) && length >= 0 ? length : undefined;
}

/** MD5 digest from an R2 ETag (single-part uploads use the MD5 as ETag). */
export function md5FromEtag(etag) {
  const value = String(etag || '').replace(/^W\//, '').replace(/"/g, '');
  return /^[a-f0-9]{32}$/i.test(value) ? value.toLowerCase() : null;
}

async function readRange(env, key, offset, length) {
  const object = await env.BUCKET.get(key, { range: { offset, length } });
  if (object === null || object === undefined) return null;
  return new Uint8Array(await object.arrayBuffer());
}

function readString(bytes, start, length) {
  let end = start;
  while (end < start + length && bytes[end] !== 0) end += 1;
  return new TextDecoder().decode(bytes.subarray(start, end));
}

function parseOctal(bytes, start, length) {
  let text = '';
  for (let index = start; index < start + length; index += 1) {
    const code = bytes[index];
    if (code === 0 || code === 0x20) break;
    text += String.fromCharCode(code);
  }
  const value = parseInt(text.trim(), 8);
  return Number.isFinite(value) ? value : 0;
}

/**
 * Read the parts of an SPK that the index needs, straight from R2 ranges.
 * @returns {Promise<{info: Uint8Array|null, icons: object, screens: object, wizard: boolean, privilege: Uint8Array|null}>}
 */
export async function readSpkParts(env, key) {
  const parts = { info: null, icons: {}, screens: {}, wizard: false, privilege: null };
  let offset = 0;
  for (let guard = 0; guard < 128; guard += 1) {
    const header = await readRange(env, key, offset, BLOCK);
    if (header === null || header.byteLength < BLOCK) break;
    if (header.every((byte) => byte === 0)) break;
    const name = readString(header, 0, 100).replace(/\\/g, '/').replace(/^\.\//, '');
    const size = parseOctal(header, 124, 12);
    const type = header[156];
    const contentOffset = offset + BLOCK;

    if (type === 0x35 || name.endsWith('/')) {
      if (name.replace(/\/+$/, '') === 'WIZARD_UIFILES') parts.wizard = true;
    } else if (name === 'INFO') {
      if (size > MAX_INFO_BYTES) throw new Error('INFO exceeds the size limit');
      parts.info = await readRange(env, key, contentOffset, size);
    } else if (name === 'PACKAGE_ICON.PNG' && size > 0 && size <= MAX_IMAGE_BYTES) {
      parts.icons[72] = await readRange(env, key, contentOffset, size);
    } else if (name === 'PACKAGE_ICON_256.PNG' && size > 0 && size <= MAX_IMAGE_BYTES) {
      parts.icons[120] = await readRange(env, key, contentOffset, size);
    } else if (name === 'conf/privilege' && size > 0 && size <= 1024 * 1024) {
      parts.privilege = await readRange(env, key, contentOffset, size);
    } else {
      const screen = SCREEN_NAME.exec(name);
      if (screen !== null && size > 0 && size <= MAX_IMAGE_BYTES) {
        parts.screens[Number(screen[1])] = await readRange(env, key, contentOffset, size);
      }
    }
    offset = contentOffset + Math.ceil(size / BLOCK) * BLOCK;
  }
  if (parts.info === null) throw new Error('archive has no INFO');
  return parts;
}

/**
 * Extract the metadata entries of an SPK from a byte stream without buffering
 * the whole file: some packages are >128 MB, above the Workers memory limit.
 */
export class SpkTarScanner {
  constructor() {
    this.parts = { info: null, icons: {}, screens: {}, wizard: false, privilege: null };
    this.header = new Uint8Array(BLOCK);
    this.headerFill = 0;
    this.skip = 0;
    this.want = null;
    this.done = false;
  }

  push(chunk) {
    if (this.done || chunk === undefined || chunk === null || chunk.byteLength === 0) return;
    let pos = 0;
    while (pos < chunk.byteLength) {
      if (this.skip > 0) {
        const take = Math.min(this.skip, chunk.byteLength - pos);
        this.skip -= take;
        pos += take;
        continue;
      }
      if (this.want !== null) {
        const remaining = this.want.size - this.want.got;
        const take = Math.min(remaining, chunk.byteLength - pos);
        if (take > 0) {
          this.want.chunks.push(chunk.subarray(pos, pos + take));
          this.want.got += take;
          pos += take;
        }
        if (this.want.got >= this.want.size) {
          this.store(this.want);
          this.skip = this.want.padded - this.want.size;
          this.want = null;
        }
        continue;
      }
      const take = Math.min(BLOCK - this.headerFill, chunk.byteLength - pos);
      this.header.set(chunk.subarray(pos, pos + take), this.headerFill);
      this.headerFill += take;
      pos += take;
      if (this.headerFill < BLOCK) break;
      this.headerFill = 0;
      this.parseHeader();
    }
  }

  parseHeader() {
    const header = this.header;
    if (header.every((byte) => byte === 0)) {
      this.done = true;
      return;
    }
    const name = readString(header, 0, 100).replace(/\\/g, '/').replace(/^\.\//, '');
    const size = parseOctal(header, 124, 12);
    const type = header[156];
    const padded = Math.ceil(size / BLOCK) * BLOCK;
    if (type === 0x35 || name.endsWith('/')) {
      if (name.replace(/\/+$/, '') === 'WIZARD_UIFILES') this.parts.wizard = true;
      this.skip = padded;
      return;
    }
    const kind = this.kindOf(name, size);
    if (kind === null) {
      this.skip = padded;
      return;
    }
    if (size === 0) {
      this.skip = 0;
      return;
    }
    this.want = { kind, size, padded, got: 0, chunks: [] };
  }

  kindOf(name, size) {
    if (name === 'INFO' && size <= MAX_INFO_BYTES) return 'info';
    if (name === 'PACKAGE_ICON.PNG' && size > 0 && size <= MAX_IMAGE_BYTES) return 'icon72';
    if (name === 'PACKAGE_ICON_256.PNG' && size > 0 && size <= MAX_IMAGE_BYTES) return 'icon120';
    if (name === 'conf/privilege' && size > 0 && size <= 1024 * 1024) return 'privilege';
    const screen = SCREEN_NAME.exec(name);
    if (screen !== null && size > 0 && size <= MAX_IMAGE_BYTES) return `screen:${Number(screen[1])}`;
    return null;
  }

  store(want) {
    const output = new Uint8Array(want.size);
    let offset = 0;
    for (const chunk of want.chunks) {
      output.set(chunk, offset);
      offset += chunk.byteLength;
    }
    if (want.kind === 'info') this.parts.info = output;
    else if (want.kind === 'icon72') this.parts.icons[72] = output;
    else if (want.kind === 'icon120') this.parts.icons[120] = output;
    else if (want.kind === 'privilege') this.parts.privilege = output;
    else if (want.kind.startsWith('screen:')) this.parts.screens[Number(want.kind.slice(7))] = output;
  }

  finish() {
    if (this.parts.info === null) throw new Error('archive has no INFO');
    return this.parts;
  }
}

/**
 * Same as readSpkParts, but for an SPK already held in memory (a host source
 * download). Avoids the per-entry R2 round trips, which dominate the sync time
 * for sources with hundreds of packages.
 *
 * @param {Uint8Array|ArrayBuffer} input SPK tar bytes
 * @returns {{info: Uint8Array|null, icons: object, screens: object, wizard: boolean, privilege: Uint8Array|null}}
 */
export function readSpkPartsFromBytes(input) {
  const bytes = input instanceof Uint8Array ? input : new Uint8Array(input);
  const parts = { info: null, icons: {}, screens: {}, wizard: false, privilege: null };
  let offset = 0;
  for (let guard = 0; guard < 128; guard += 1) {
    if (offset + BLOCK > bytes.byteLength) break;
    const header = bytes.subarray(offset, offset + BLOCK);
    if (header.every((byte) => byte === 0)) break;
    const name = readString(header, 0, 100).replace(/\\/g, '/').replace(/^\.\//, '');
    const size = parseOctal(header, 124, 12);
    const type = header[156];
    const contentOffset = offset + BLOCK;
    if (type === 0x35 || name.endsWith('/')) {
      if (name.replace(/\/+$/, '') === 'WIZARD_UIFILES') parts.wizard = true;
    } else if (name === 'INFO') {
      if (size > MAX_INFO_BYTES) throw new Error('INFO exceeds the size limit');
      parts.info = bytes.subarray(contentOffset, contentOffset + size);
    } else if (name === 'PACKAGE_ICON.PNG' && size > 0 && size <= MAX_IMAGE_BYTES) {
      parts.icons[72] = bytes.subarray(contentOffset, contentOffset + size);
    } else if (name === 'PACKAGE_ICON_256.PNG' && size > 0 && size <= MAX_IMAGE_BYTES) {
      parts.icons[120] = bytes.subarray(contentOffset, contentOffset + size);
    } else if (name === 'conf/privilege' && size > 0 && size <= 1024 * 1024) {
      parts.privilege = bytes.subarray(contentOffset, contentOffset + size);
    } else {
      const screen = SCREEN_NAME.exec(name);
      if (screen !== null && size > 0 && size <= MAX_IMAGE_BYTES) {
        parts.screens[Number(screen[1])] = bytes.subarray(contentOffset, contentOffset + size);
      }
    }
    offset = contentOffset + Math.ceil(size / BLOCK) * BLOCK;
  }
  if (parts.info === null) throw new Error('archive has no INFO');
  return parts;
}

export function parseInfo(bytes) {
  const text = new TextDecoder().decode(bytes);
  const info = {};
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trimEnd();
    if (line.trim() === '' || line.trimStart().startsWith('#')) continue;
    const match = INFO_LINE.exec(line);
    if (!match) continue;
    info[match[1]] = decodeInfoValue(match[2].trim());
  }
  return info;
}

function decodeInfoValue(raw) {
  if (raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"')) {
    return raw.slice(1, -1).replace(/\\(.)/g, (_, character) => {
      if (character === 'n') return '\n';
      if (character === 't') return '\t';
      return character;
    });
  }
  return raw;
}

function normaliseList(value, lowercase = false) {
  const items = String(value || '').split(/\s+/).filter(Boolean);
  const seen = new Set();
  for (const item of items) seen.add(lowercase ? item.toLowerCase() : item);
  return [...seen];
}

function parseBool(value) {
  return ['yes', 'true', '1'].includes(String(value || '').trim().toLowerCase());
}

function isUnsignedInt32(value) {
  if (!/^\d+$/.test(value)) return false;
  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 && number <= 4294967295;
}

function isValidDsmVersion(version) {
  const match = DSM_VERSION.exec(version);
  if (match === null) return false;
  return match.slice(1).every((part) => part === undefined || isUnsignedInt32(part));
}

function isValidPackageVersion(version) {
  if (PACKAGE_VERSION.exec(version) === null) return false;
  return version.split(/[._-]/).every(isUnsignedInt32);
}

function runsAsRoot(info, privilegeBytes) {
  for (const [key, value] of Object.entries(info)) {
    if (!key.toLowerCase().startsWith('description')) continue;
    const text = String(value).toLowerCase();
    if (text.includes('root权限') || text.includes('root privileges')) return true;
  }
  if (privilegeBytes === null || privilegeBytes === undefined) return false;
  let bytes = privilegeBytes;
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) bytes = bytes.subarray(3);
  try {
    const privilege = JSON.parse(new TextDecoder().decode(bytes));
    return Boolean(privilege && privilege.defaults && String(privilege.defaults['run-as']).trim().toLowerCase() === 'root');
  } catch {
    return false;
  }
}

function safeStem(file) {
  const stem = String(file).replace(/\.spk$/i, '').replace(/[^A-Za-z0-9._-]+/g, '_').replace(/^[._]+|[._]+$/g, '');
  return (stem || 'package').slice(0, 80);
}

async function writeIcon(env, name, bytes) {
  await env.BUCKET.put(`spk/icons/${name}`, bytes, {
    httpMetadata: { contentType: 'image/png', cacheControl: 'public, max-age=31536000, immutable' },
  });
  // Index records reference icons relative to the Worker origin (icons/...).
  return `icons/${name}`;
}

/** Ensure the placeholder icons referenced by records without an SPK icon exist. */
export async function ensureDefaultIcons(env) {
  await writeIcon(env, '_default_72.png', decodeBase64(DEFAULT_ICON_72_BASE64));
  await writeIcon(env, '_default_120.png', decodeBase64(DEFAULT_ICON_120_BASE64));
}

/**
 * Build one index record from an SPK already stored in R2.
 *
 * @param {object} env worker env (BUCKET)
 * @param {{file: string, parts: object, size: number, md5: string}} input
 * @returns {Promise<object>} record (also writes its icons to R2)
 */
export async function buildRecord(env, { file, parts, size, md5 }) {
  const info = parseInfo(parts.info);
  for (const field of REQUIRED_INFO_FIELDS) {
    if (String(info[field] || '').trim() === '') throw new Error(`INFO missing field: ${field}`);
  }
  if (!ARCH_LIST.test(info.arch.trim())) throw new Error('INFO arch is invalid');
  if (!isValidPackageVersion(info.version)) throw new Error('INFO version is invalid');
  if (!isValidDsmVersion(info.os_min_ver.trim())) throw new Error('INFO os_min_ver is invalid');
  const osMaxVer = String(info.os_max_ver || '').trim();
  if (osMaxVer !== '' && !isValidDsmVersion(osMaxVer)) throw new Error('INFO os_max_ver is invalid');

  const stem = safeStem(file);
  const record = {
    file,
    package: info.package,
    version: info.version,
    displayname: info.displayname || info.package,
    description: info.description,
    os_min_ver: info.os_min_ver.trim(),
    os_max_ver: osMaxVer,
    arch: normaliseList(info.arch, true),
    exclude_arch: normaliseList(info.exclude_arch, true),
    model: normaliseList(info.model, true),
    exclude_model: normaliseList(info.exclude_model, true),
    beta: parseBool(info.beta),
    official: false,
    run_as_root: runsAsRoot(info, parts.privilege),
    silent_install: parseBool(info.silent_install),
    silent_uninstall: parseBool(info.silent_uninstall),
    silent_upgrade: parseBool(info.silent_upgrade),
    auto_upgrade_from: info.auto_upgrade_from || '',
    install_dep_packages: info.install_dep_packages || '',
    install_dep_services: info.start_dep_services || '',
    install_conflict_packages: info.install_conflict_packages || '',
    maintainer: info.maintainer || '',
    maintainer_url: info.maintainer_url || '',
    distributor: info.distributor || '',
    distributor_url: info.distributor_url || '',
    support_url: info.support_url || '',
    changelog: info.changelog || '',
    filesize: size,
    md5,
  };

  const defaultQ = !parts.wizard;
  for (const flag of ['qinst', 'qstart', 'qupgrade']) {
    record[flag] = flag in info ? parseBool(info[flag]) : defaultQ;
  }
  for (const [key, value] of Object.entries(info)) {
    if (LOCALIZED_KEY.test(key)) record[key] = value;
  }

  const thumbnail = [];
  for (const sizeKey of ['72', '120']) {
    const image = parts.icons[sizeKey];
    if (image !== undefined && image !== null && image.byteLength > 0) {
      thumbnail.push(await writeIcon(env, `${stem}_thumb_${sizeKey}.png`, image));
    } else {
      thumbnail.push(sizeKey === '72' ? DEFAULT_ICON_72 : DEFAULT_ICON_120);
    }
  }
  record.thumbnail = thumbnail;

  const snapshots = [];
  for (const number of Object.keys(parts.screens).map(Number).sort((a, b) => a - b)) {
    snapshots.push(await writeIcon(env, `${stem}_screen_${number}.png`, parts.screens[number]));
  }
  record.snapshot = snapshots;

  return record;
}
